-- ========== TABLES & VIEWS ==========

-- [view] dep_cycles
CREATE VIEW dep_cycles AS
        WITH RECURSIVE
        cycle_nodes AS (
          SELECT DISTINCT from_node_id AS node_id FROM edges e1
          WHERE EXISTS (
            SELECT 1 FROM edges e2
            WHERE e2.from_node_id = e1.to_node_id
            AND e2.to_node_id = e1.from_node_id
          )
          UNION
          SELECT DISTINCT to_node_id AS node_id FROM edges e1
          WHERE EXISTS (
            SELECT 1 FROM edges e2
            WHERE e2.from_node_id = e1.to_node_id
            AND e2.to_node_id = e1.from_node_id
          )
        )
        SELECT
          n.node_id,
          n.path,
          n.domain_id,
          n.design_maturity
        FROM cycle_nodes c
        JOIN nodes n ON c.node_id = n.node_id
        ORDER BY n.domain_id, n.node_id;

-- [table] _schema_version
CREATE TABLE _schema_version (
        version INTEGER PRIMARY KEY,
        applied_at TEXT NOT NULL,
        description TEXT
    );

-- [table] arch_constraints
CREATE TABLE arch_constraints (
        constraint_id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        constraint_type TEXT NOT NULL,
        from_domain TEXT,
        to_domain TEXT,
        rule_definition TEXT NOT NULL,
        severity TEXT DEFAULT 'hard',
        enforcement TEXT DEFAULT 'gate',
        description TEXT, violation_status TEXT DEFAULT 'open', details TEXT, detected_at TEXT,
        FOREIGN KEY (from_domain) REFERENCES domains(domain_id),
        FOREIGN KEY (to_domain) REFERENCES domains(domain_id)
    );

-- [table] arch_directory_tree
CREATE TABLE "arch_directory_tree" (
    path             TEXT    PRIMARY KEY,
    parent_path      TEXT,
    path_type        TEXT    NOT NULL,
    domain_id        TEXT,
    blueprint_id     TEXT,
    change_policy    TEXT,
    modification_permission TEXT,
    build_status     TEXT    DEFAULT 'unbuilt',
    design_maturity  TEXT    NOT NULL DEFAULT 'design',
    last_scanned     TEXT
);

-- [table] arch_path_mappings
CREATE TABLE arch_path_mappings (
        mapping_id INTEGER PRIMARY KEY AUTOINCREMENT,
        domain_id TEXT NOT NULL,
        path_pattern TEXT NOT NULL,
        path_type TEXT NOT NULL,
        state TEXT NOT NULL DEFAULT 'design',
        covers TEXT,
        aliases TEXT,
        FOREIGN KEY (domain_id) REFERENCES domains(domain_id)
    );

-- [table] blueprint_links
CREATE TABLE blueprint_links (
            blueprint_id       TEXT PRIMARY KEY,
            blueprint_path     TEXT NOT NULL,
            alignment_verified INTEGER DEFAULT 0,
            last_verified      TEXT
        );

-- [table] business_streams
CREATE TABLE business_streams (
            stream_id      TEXT PRIMARY KEY,
            name           TEXT NOT NULL,
            goal           TEXT,
            input          TEXT,
            output         TEXT,
            runtime_plane  TEXT,
            CHECK (runtime_plane IN ('data_plane', 'control_plane', 'management_plane'))
        );

-- [table] contracts
CREATE TABLE contracts (
        contract_id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        provider_domain TEXT NOT NULL,
        consumer_domain TEXT NOT NULL,
        contract_type TEXT NOT NULL,
        schema_definition TEXT,
        version TEXT, promise TEXT, actual_consumer TEXT, fulfillment_status TEXT DEFAULT 'unresolved', gap TEXT, target_phase TEXT, last_reviewed TEXT,
        FOREIGN KEY (provider_domain) REFERENCES domains(domain_id),
        FOREIGN KEY (consumer_domain) REFERENCES domains(domain_id)
    );

-- [table] cross_registry_rules
CREATE TABLE cross_registry_rules (
            rule_id         TEXT PRIMARY KEY,
            title           TEXT NOT NULL,
            fields          TEXT,
            ssot            TEXT NOT NULL,
            consistency     TEXT,
            violation_action TEXT,
            CHECK (consistency IN ('exact', 'derived', 'independent')),
            CHECK (violation_action IN ('block', 'warn', 'log'))
        );

-- [table] derived_identifier_registry
CREATE TABLE derived_identifier_registry (
        derived_type        TEXT NOT NULL,
        source_field        TEXT NOT NULL,
        derived_field       TEXT NOT NULL,
        derivation_rule     TEXT NOT NULL,
        propagation_method  TEXT NOT NULL DEFAULT 'exact_value_map',
        source_doc          TEXT,
        PRIMARY KEY (derived_type, derived_field)
    );

-- [table] domain_dependencies
CREATE TABLE domain_dependencies (
        from_domain TEXT NOT NULL,
        to_domain TEXT NOT NULL,
        edge_count INTEGER DEFAULT 0,
        edge_types TEXT,
        constraint_type TEXT,
        PRIMARY KEY (from_domain, to_domain),
        FOREIGN KEY (from_domain) REFERENCES domains(domain_id),
        FOREIGN KEY (to_domain) REFERENCES domains(domain_id)
    );

-- [table] domain_events
CREATE TABLE domain_events (
        event_id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        source_domain TEXT NOT NULL,
        target_domains TEXT,
        payload_schema TEXT,
        priority TEXT DEFAULT 'P1', event_type TEXT DEFAULT 'domain_event',
        FOREIGN KEY (source_domain) REFERENCES domains(domain_id)
    );

-- [table] domain_mapping
CREATE TABLE domain_mapping (
            mapping_id INTEGER PRIMARY KEY AUTOINCREMENT,
            path_prefix TEXT NOT NULL,
            domain_id TEXT NOT NULL,
            subdomain_id TEXT,
            mapping_type TEXT NOT NULL,
            mapped_at TEXT NOT NULL,
            mapped_by TEXT NOT NULL,
            note TEXT
        );

-- [table] domain_naming_rules
CREATE TABLE domain_naming_rules (
        rule_id      TEXT PRIMARY KEY,
        rule_name    TEXT NOT NULL,
        rule_text    TEXT NOT NULL,
        applies_to   TEXT NOT NULL DEFAULT 'create',
        severity     TEXT NOT NULL DEFAULT 'error',
        example_bad  TEXT,
        example_good TEXT,
        created_at   TEXT NOT NULL,
        source_doc   TEXT
    );

-- [table] domains
CREATE TABLE domains (
        domain_id TEXT PRIMARY KEY,
        domain_name TEXT NOT NULL,
        domain_group TEXT NOT NULL,
        description TEXT,
        ssot_path TEXT,
        current_modules INTEGER DEFAULT 0,
        max_modules INTEGER,
        lifecycle TEXT DEFAULT 'design_only',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
    , build_status TEXT DEFAULT 'unbuilt', modification_permission TEXT, layer_id TEXT, target_modules INTEGER, production_nodes INTEGER DEFAULT 0);

-- [table] edges
CREATE TABLE "edges" (
            edge_id INTEGER PRIMARY KEY AUTOINCREMENT,
            from_node_id INTEGER NOT NULL,
            to_node_id INTEGER NOT NULL,
            dep_type TEXT, architecture_direction TEXT, coupling_strength TEXT,
            used_symbol TEXT, invocation_method TEXT, api_contract_refs TEXT,
            event_ref TEXT, ddd_integration_pattern TEXT, failure_mode TEXT,
            fallback TEXT, activation_condition TEXT, data_transfer_description TEXT,
            resource_impact TEXT, relationship_type TEXT, cross_domain INTEGER,
            verified INTEGER, dep_maturity TEXT DEFAULT 'active', valid_since TEXT, is_legal_cycle INTEGER DEFAULT 0,
            FOREIGN KEY (from_node_id) REFERENCES "nodes"(node_id),
            FOREIGN KEY (to_node_id) REFERENCES "nodes"(node_id)
        );

-- [table] field_vocabularies
CREATE TABLE field_vocabularies (
            field_name     TEXT NOT NULL,
            value          TEXT NOT NULL,
            definition     TEXT,
            ai_consumption TEXT,
            source_yaml    TEXT,
            PRIMARY KEY (field_name, value)
        );

-- [table] gates
CREATE TABLE gates (
            gate_id        TEXT PRIMARY KEY,
            name           TEXT NOT NULL,
            entry          TEXT NOT NULL,
            description    TEXT,
            files_trigger  TEXT,
            always_run     INTEGER DEFAULT 0,
            category       TEXT NOT NULL,
            status         TEXT DEFAULT 'active',
            source         TEXT DEFAULT '.pre-commit-config.yaml', event_driven TEXT DEFAULT '', auto_start INTEGER DEFAULT 1,
            CHECK (status IN ('active', 'deprecated', 'disabled'))
        );

-- [table] governance_audit_logs
CREATE TABLE governance_audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT NOT NULL, total_gates INTEGER DEFAULT 0, passed_gates INTEGER DEFAULT 0, failed_gates INTEGER DEFAULT 0, skipped_gates INTEGER DEFAULT 0, success INTEGER DEFAULT 0, errors TEXT DEFAULT '');

-- [table] hard_boundaries
CREATE TABLE hard_boundaries (
            boundary_id    TEXT PRIMARY KEY,
            category       TEXT NOT NULL,
            constraint_def TEXT NOT NULL,
            parameters     TEXT,
            impact         TEXT,
            CHECK (category IN ('architectural', 'domain', 'data', 'security', 'operational'))
        );

-- [table] infrastructure_components
CREATE TABLE infrastructure_components (
            component_id    TEXT PRIMARY KEY,
            component_type  TEXT NOT NULL,
            address         TEXT,
            health_check    TEXT,
            dependencies    TEXT,
            sla             TEXT,
            status          TEXT DEFAULT 'active',
            CHECK (component_type IN ('event_bus', 'message_queue', 'relational_db',
                                       'vector_db', 'cache', 'object_storage',
                                       'config_center', 'service_registry', 'ci_pipeline'))
        );

-- [table] model_capabilities
CREATE TABLE model_capabilities (
            model_name              TEXT PRIMARY KEY,
            tier                    TEXT NOT NULL,
            max_files_per_session   INTEGER,
            allowed_paths           TEXT,
            forbidden_paths         TEXT,
            recommended_tasks       TEXT,
            forbidden_tasks         TEXT,
            CHECK (tier IN ('premium', 'standard', 'free', 'api'))
        );

-- [table] nodes
CREATE TABLE "nodes" (
    node_id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    node_type                TEXT,
    path                     TEXT,
    granularity              TEXT,
