-- trigger on nodes: chk_nodes_blueprint_id_insert
CREATE TRIGGER chk_nodes_blueprint_id_insert
            BEFORE INSERT ON nodes
            WHEN NEW.blueprint_id IS NOT NULL
              AND NEW.blueprint_id != ''
              AND NEW.blueprint_id_invalid = 0
              AND NEW.blueprint_id NOT GLOB 'MOD-*'
              AND NEW.blueprint_id NOT GLOB 'D-*'
              AND NEW.blueprint_id NOT GLOB 'SH-*'
              AND NEW.blueprint_id NOT GLOB 'PLACEHOLDER*'
            BEGIN
                SELECT RAISE(ABORT, 'nodes.blueprint_id format violation (裁定#208 双轨制+历史兼容: MOD-*/D-*/SH-*/PLACEHOLDER*, or set blueprint_id_invalid=1 for legacy)');
            END;

