-- trigger on nodes: trg_nodes_delete_cleanup_edges
CREATE TRIGGER trg_nodes_delete_cleanup_edges
            AFTER DELETE ON nodes
            BEGIN
                DELETE FROM edges WHERE from_node_id = OLD.node_id OR to_node_id = OLD.node_id;
            END;

